def solve2(inp, exclude):
    h, w = inp.shape
    nzr = [r for r in range(h) if (inp[r]!=0).any()]
    nzc = [c for c in range(w) if (inp[:,c]!=0).any()]
    def groups(idx):
        g=[]; s=idx[0]; p=idx[0]
        for i in idx[1:]:
            if i==p+1: p=i
            else: g.append((s,p)); s=i; p=i
        g.append((s,p)); return g
    br = [g for g in groups(nzr) if g[1]-g[0]>1]
    bc = [g for g in groups(nzc) if g[1]-g[0]>1]
    centers = np.zeros((len(br), len(bc)), int)
    for i,(r0,r1) in enumerate(br):
        for j,(c0,c1) in enumerate(bc):
            vals = inp[r0:r1+1, c0:c1+1][1:-1,1:-1].ravel()
            centers[i,j] = Counter(vals).most_common(1)[0][0]
    out = inp.copy()
    for color in set(centers.ravel()):
        if color == exclude: continue
        pos = [(i,j) for i in range(centers.shape[0]) for j in range(centers.shape[1]) if centers[i,j]==color]
        rows_ = defaultdict(list); cols_ = defaultdict(list)
        for i,j in pos: rows_[i].append(j); cols_[j].append(i)
        for i,js in rows_.items():
            js=sorted(js)
            rspan = range(br[i][0]+1, br[i][1])  # full inner thickness
            for k in range(len(js)-1):
                for j in range(js[k], js[k+1]):
                    for c in range(bc[j][1]+1, bc[j+1][0]):
                        for r in rspan: out[r,c]=color
        for j,is_ in cols_.items():
            is_=sorted(is_)
            cspan = range(bc[j][0]+1, bc[j][1])
            for k in range(len(is_)-1):
                for i in range(is_[k], is_[k+1]):
                    for r in range(br[i][1]+1, br[i+1][0]):
                        for c in cspan: out[r,c]=color
    return out

