def centers_of(inp):
    h,w = inp.shape
    nzr=[r for r in range(h) if (inp[r]!=0).any()]; nzc=[c for c in range(w) if (inp[:,c]!=0).any()]
    def groups(idx):
        g=[]; s=idx[0]; p=idx[0]
        for i in idx[1:]:
            if i==p+1: p=i
            else: g.append((s,p)); s=i; p=i
        g.append((s,p)); return g
    gr,gc = groups(nzr),groups(nzc)
    mr=C(g[1]-g[0]+1 for g in gr).most_common(1)[0][0]
    mc=C(g[1]-g[0]+1 for g in gc).most_common(1)[0][0]
    br=[g for g in gr if g[1]-g[0]+1==mr]; bc=[g for g in gc if g[1]-g[0]+1==mc]
    cen=np.zeros((len(br),len(bc)),int)
    for i,(r0,r1) in enumerate(br):
        for j,(c0,c1) in enumerate(bc):
            cen[i,j]=C(inp[r0:r1+1,c0:c1+1][1:-1,1:-1].ravel()).most_common(1)[0][0]
