def solve5(inp, exclude):
    br,bc,cen = centers_of(inp)
    out = inp.copy()
    for color in set(cen.ravel()):
        if color==exclude: continue
        rows_=defaultdict(list); cols_=defaultdict(list)
        for i in range(cen.shape[0]):
            for j in range(cen.shape[1]):
                if cen[i,j]==color: rows_[i].append(j); cols_[j].append(i)
        for i,js in rows_.items():
            js=sorted(js)
            for k in range(len(js)-1):
                for j in range(js[k],js[k+1]):
                    for c in range(bc[j][1]+1, bc[j+1][0]):
                        for r in range(br[i][0]+1, br[i][1]): out[r,c]=color
        for j,is_ in cols_.items():
            is_=sorted(is_)
            for k in range(len(is_)-1):
                for i in range(is_[k],is_[k+1]):
                    for r in range(br[i][1]+1, br[i+1][0]):
                        for c in range(bc[j][0]+1, bc[j][1]): out[r,c]=color
    return out

